glsl4.vert:
precision highp float;
layout(set = 0, binding = 0) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
};
layout(set = 0, binding = 1) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(location = 0) in vec3 a_position;
layout(location = 1) in vec2 a_texCoord;
layout(location = 2) in vec4 a_color;
layout(location = 0) out vec4 color;
layout(location = 1) out vec2 uv0;
layout(location = 2) out vec4 lightSweepUV;
#if USE_LIGHT_SWEEP
layout(set = 1, binding = 0) uniform vertData {
  float lightSweepSpeed;
  float lightSweepRange;
  float lightSweepUVX;
  float lightSweepUVY;
};
#endif
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_PIXEL_ALIGNMENT
    pos = cc_matView * pos;
    pos.xyz = floor(pos.xyz);
    pos = cc_matProj * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
#if USE_LIGHT_SWEEP
  float time = mod(cc_time.x * lightSweepSpeed, lightSweepRange) - (lightSweepRange / 2.0);
  #if USE_LOCAL
    lightSweepUV.xy = vec2(-time * lightSweepUVX, -time * lightSweepUVY);
  #else
    vec2 screenViewXY = pos.xy;
    screenViewXY.x = screenViewXY.x / pos.w;
    screenViewXY.y = -screenViewXY.y / pos.w;
    vec2 screenViewUV = screenViewXY * 0.5 + 0.5;
    lightSweepUV.xy = (screenViewUV + vec2(-time * lightSweepUVX, -time * lightSweepUVY));
  #endif
#endif
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl4.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(set = 1, binding = 1) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
layout(location = 0) in vec4 color;
layout(location = 2) in vec4 lightSweepUV;
#if USE_TEXTURE
  layout(location = 1) in vec2 uv0;
  layout(set = 2, binding = 10) uniform sampler2D cc_spriteTexture;
#endif
#if USE_LIGHT_SWEEP
  layout(set = 1, binding = 3) uniform sampler2D lightSweepTex;
  layout(set = 1, binding = 2) uniform fragData {
    vec4 lightSweepColor;
    float lightSweepPower;
    float lightSweepUVPowerX;
    float lightSweepUVPowerY;
    float lightSweepCompared;
  };
#endif
vec2 saturate(in vec2 v) {
  return vec2(clamp(v.x, 0.0, 1.0), clamp(v.y, 0.0, 1.0));
}
vec4 frag () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
    o *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0) * color;
  #endif
  #if USE_LIGHT_SWEEP
    float luminosity = 0.299 * o.r + 0.587 * o.g + 0.114 * o.b;
    vec2 lightUV = vec2(luminosity  * lightSweepUVPowerX, luminosity  * lightSweepUVPowerY);
    vec4 lightSweepColor = CCSampleWithAlphaSeparated(lightSweepTex, saturate(lightSweepUV.xy + lightUV)) * lightSweepColor;
    lightSweepColor *= lightSweepColor.a * o.a;
    lightSweepColor *= lightSweepPower;
    o = o + pow(o, vec4(lightSweepCompared)) * lightSweepColor;
  #endif
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

